const menuToggle=document.querySelector('.menu-toggle');const navLinks=document.querySelector('.nav-links');menuToggle?.addEventListener('click',()=>navLinks.classList.toggle('open'));document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>navLinks.classList.remove('open')));
const filters=document.querySelectorAll('.filter');const cards=document.querySelectorAll('.project-card');filters.forEach(filter=>filter.addEventListener('click',()=>{filters.forEach(f=>f.classList.remove('active'));filter.classList.add('active');const type=filter.dataset.filter;cards.forEach(card=>card.classList.toggle('hidden',type!=='all'&&card.dataset.type!==type));}));
const cases={kahve:{title:'Kahve Lab',summary:'Sıcak bir marka hissini hızlı ve iştah açıcı bir kafe deneyimine dönüştüren konsept web sitesi.',problem:'Menü, atmosfer ve konum bilgisi dağınık olan bir kafenin ilk ziyaret kararını hızlandırmak.',solution:'Ürün odaklı hero, menü keşfi, şube/konum CTA’sı ve mobil öncelikli rezervasyon akışı.',scope:'Marka hissi · web arayüzü · menü mimarisi · mobil deneyim'},rentacar:{title:'Northline Rent A Car',summary:'Araç keşfi ve rezervasyon niyetini tek akışta buluşturan konsept Rent A Car deneyimi.',problem:'Kullanıcının araç tipi, tarih ve teslim noktasını hızlıca seçebilmesi.',solution:'Filtrelenebilir araç vitrini, güven unsurları, hızlı teklif formu ve net telefon/WhatsApp CTA’sı.',scope:'Kurumsal web · araç filtreleme · rezervasyon formu · yerel SEO'},wallet:{title:'Ada Wallet',summary:'Günlük finans takibini sadeleştiren, koyu arayüzlü mobil ürün konsepti.',problem:'Bakiye, harcama ve kategori bilgisini tek bakışta anlaşılır kılmak.',solution:'Özet dashboard, grafikler, harcama kategorileri ve görev odaklı mobil navigasyon.',scope:'Ürün fikri · mobil UX · dashboard · prototip yaklaşımı'},mola:{title:'Mola Coffee',summary:'Kahve markası için ambalaj, fotoğraf ve dijital vitrin hissini birleştiren konsept kimlik.',problem:'Yeni bir kahve markasına raf ve ekran üzerinde ayırt edici bir karakter kazandırmak.',solution:'Sıcak fotoğraf dili, yalın ambalaj sistemi, ürün hikâyesi ve abonelik/e-ticaret yönü.',scope:'Marka kimliği · art direction · e-ticaret fikri · içerik dili'},basari:{title:'Başarı Atölyesi',summary:'Dershane ve eğitim markaları için kurs keşfi ve öğrenci ilerlemesini görünür kılan konsept platform.',problem:'Kurs, öğretmen ve ilerleme bilgilerinin hem öğrenci hem veli için kolay anlaşılması.',solution:'Kurs kartları, ilerleme göstergeleri, sınav/etüt akışı ve danışma CTA’sı.',scope:'Eğitim web sitesi · öğrenci paneli · içerik mimarisi · mobil uyum'},archive:{title:'Archive Studio',summary:'Yaratıcı bir stüdyo için editoryal, rafine ve teknolojiyle dengelenmiş marka kimliği konsepti.',problem:'Stüdyonun tasarım yaklaşımını sade ama ayırt edilebilir bir görsel sistemle anlatmak.',solution:'Tipografi, renk, grid, sunum şablonları ve case-study odaklı dijital vitrin.',scope:'Marka sistemi · sunum dili · portföy deneyimi · içerik şablonu'}};
const modal=document.querySelector('#case-modal');const openCase=key=>{const data=cases[key];if(!data||!modal)return;modal.querySelector('#case-title').textContent=data.title;modal.querySelector('#case-summary').textContent=data.summary;modal.querySelector('#case-problem').textContent=data.problem;modal.querySelector('#case-solution').textContent=data.solution;modal.querySelector('#case-scope').textContent=data.scope;modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');};document.querySelectorAll('.case-open').forEach(btn=>btn.addEventListener('click',()=>openCase(btn.dataset.case)));document.querySelectorAll('[data-close-case]').forEach(el=>el.addEventListener('click',()=>{modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');}});
const form=document.querySelector('#contact-form');form?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const subject=encodeURIComponent(`Ada Web proje görüşmesi — ${data.get('name')}`);const body=encodeURIComponent(`Ad: ${data.get('name')}\nE-posta: ${data.get('email')}\n\nProje:\n${data.get('project')}`);window.location.href=`mailto:adaweb@gmail.com?subject=${subject}&body=${body}`;});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
